-- Realistic GSO inventory, generated by generate_realistic_seed.py. Deletes ALL asset data first.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;
DELETE FROM `maintenance_items`;
DELETE FROM `maintenance_photos`;
DELETE FROM `maintenance_summaries`;
DELETE FROM `maintenance_ledger`;
DELETE FROM `deleted_maintenance`;
DELETE FROM `disposal_justifications`;
DELETE FROM `disposal_ledger`;
DELETE FROM `deleted_disposal`;
DELETE FROM `asset_par_issuances`;
DELETE FROM `property_return_slips`;
DELETE FROM `asset_transfer_requests`;
DELETE FROM `asset_history`;
DELETE FROM `evidence_photos`;
DELETE FROM `ai_recommendations`;
DELETE FROM `request_reminders`;
DELETE FROM `deleted_assets`;
DELETE FROM `device_records`;
DELETE FROM `equipment_records`;
DELETE FROM `audit_log_digests`;
DELETE FROM `assets`;
DELETE FROM audit_logs WHERE module IN ('Assets','AssetHistory','Maintenance','Disposal','Transfer','Transfers','Reports');
COMMIT;
ALTER TABLE `assets` AUTO_INCREMENT = 1;
ALTER TABLE `asset_history` AUTO_INCREMENT = 1;
ALTER TABLE `maintenance_ledger` AUTO_INCREMENT = 1;
ALTER TABLE `maintenance_items` AUTO_INCREMENT = 1;
ALTER TABLE `disposal_ledger` AUTO_INCREMENT = 1;
ALTER TABLE `asset_transfer_requests` AUTO_INCREMENT = 1;
ALTER TABLE `property_return_slips` AUTO_INCREMENT = 1;
ALTER TABLE `asset_par_issuances` AUTO_INCREMENT = 1;
SET FOREIGN_KEY_CHECKS = 1;
START TRANSACTION;
